#!/usr/bin/env node
import { execFileSync } from 'node:child_process'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { pathToFileURL } from 'node:url'

const here = import.meta.dirname
const source = path.resolve(here, '../..')
const output = path.join(here, 'Dockerfile')
const header = [
  '# Generated by sync-compose-build.mjs from the reviewed full-build recipe.',
  '# Do not edit this file directly.',
  '# Refresh: node deploy/lobehub/sync-compose-build.mjs --write',
  '# Verify: node deploy/lobehub/sync-compose-build.mjs --check',
  '# Build context: repository root; additional context integration: deploy/lobehub.',
  '',
].join('\n')

export function syncComposeBuild({ check = true, target = output } = {}) {
  const runtime = fs.mkdtempSync(path.join(os.tmpdir(), 'lobe-compose-build-'))
  try {
    fs.writeFileSync(path.join(runtime, 'ownership-manifest.json'), '{}')
    const pins = JSON.parse(fs.readFileSync(path.join(here, 'dependencies/build-pins.json'), 'utf8'))
    // The existing generator remains the only owner of dependency transformations.
    execFileSync(process.execPath, [
      path.join(here, 'prepare-build.mjs'), source, runtime, pins.corepack,
    ], { stdio: 'pipe' })
    const expected = header + fs.readFileSync(path.join(runtime, 'Dockerfile.lobehub'), 'utf8')
    if (check) {
      const actual = fs.existsSync(target) ? fs.readFileSync(target, 'utf8').replaceAll('\r\n', '\n') : null
      if (actual !== expected) {
        throw new Error('Compose Dockerfile is missing or stale; run node deploy/lobehub/sync-compose-build.mjs --write')
      }
    } else {
      fs.writeFileSync(target, expected)
    }
    return expected
  } finally {
    if (path.dirname(path.resolve(runtime)) !== path.resolve(os.tmpdir()) || !path.basename(runtime).startsWith('lobe-compose-build-')) {
      throw new Error('Unexpected temporary build directory')
    }
    fs.rmSync(runtime, { recursive: true, force: true })
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const mode = process.argv[2] || '--check'
  if (!['--check', '--write'].includes(mode) || process.argv.length > 3) {
    throw new Error('Usage: node deploy/lobehub/sync-compose-build.mjs [--check|--write]')
  }
  syncComposeBuild({ check: mode === '--check' })
  console.log(mode === '--check' ? 'Compose Dockerfile matches the frozen full-build recipe.' : 'Compose Dockerfile regenerated.')
}
